begin;
create or replace function public.afirma(ok boolean,msg text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FALHOU: %',msg; end if; raise notice 'ok: %',msg; end $$;
insert into public.lojas(id,nome,slug) values('aaaaaaaa-0000-0000-0000-000000000001','A','chat-a'),('bbbbbbbb-0000-0000-0000-000000000002','B','chat-b');
insert into public.usuarios_loja(loja_id,user_id,papel) values
 ('aaaaaaaa-0000-0000-0000-000000000001','11111111-1111-1111-1111-111111111111','lojista'),
 ('aaaaaaaa-0000-0000-0000-000000000001','22222222-2222-2222-2222-222222222222','editor'),
 ('bbbbbbbb-0000-0000-0000-000000000002','33333333-3333-3333-3333-333333333333','lojista');
select public.afirma(not private.chat_recurso('aaaaaaaa-0000-0000-0000-000000000001','chat_persistente'),'flags desligadas por padrão');
insert into public.loja_recursos(loja_id,recurso,ativo) values('aaaaaaaa-0000-0000-0000-000000000001','chat_persistente',true);
create temp table turno as select public.chat_iniciar('aaaaaaaa-0000-0000-0000-000000000001','22222222-2222-2222-2222-222222222222',null,'Produto ABC','chave-segura-0001','compativel_openai') as j;
select public.afirma((select j->>'estado'='novo' from turno),'reserva criada');
select public.afirma(public.chat_iniciar('aaaaaaaa-0000-0000-0000-000000000001','22222222-2222-2222-2222-222222222222',null,'Produto ABC','chave-segura-0001','compativel_openai')->>'estado'='em_execucao','reenvio durante execução não chama provedor');
select public.afirma(public.chat_iniciar('aaaaaaaa-0000-0000-0000-000000000001','22222222-2222-2222-2222-222222222222',(select (j->>'conversa_id')::uuid from turno),'Outra pergunta','chave-segura-0002','compativel_openai')->>'estado'='em_execucao','conversa serializa turnos diferentes');
select public.chat_responder('aaaaaaaa-0000-0000-0000-000000000001','22222222-2222-2222-2222-222222222222',(select (j->>'pergunta_id')::uuid from turno),(select (j->>'turno_token')::uuid from turno),'Produto sintético', '{"simulado":true,"tokens":0,"desfecho":"ok"}');
select public.afirma(public.chat_iniciar('aaaaaaaa-0000-0000-0000-000000000001','22222222-2222-2222-2222-222222222222',null,'Produto ABC','chave-segura-0001','compativel_openai')->>'estado'='concluido','reenvio concluído recupera resposta');
select public.afirma((select count(*)=2 from public.mensagens),'duas mensagens, sem duplicação');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated"}',true);
select public.afirma((select count(*)=0 from public.conversas),'lojista não lê conversas do editor diretamente');
do $$ begin begin perform * from public.chat_ler_como_administrador('aaaaaaaa-0000-0000-0000-000000000001',(select id from public.conversas limit 1),'Motivo administrativo'); raise exception 'aceitou'; exception when insufficient_privilege then null; end; end $$;
select public.afirma(true,'leitura administrativa desligada é recusada');
do $$ begin begin insert into public.loja_recursos(loja_id,recurso,ativo) values('aaaaaaaa-0000-0000-0000-000000000001','chat_leitura_administrativa',true); raise exception 'aceitou'; exception when insufficient_privilege then null; end; end $$;
select public.afirma(true,'lojista não se concede leitura administrativa');
select set_config('request.jwt.claims','{"sub":"22222222-2222-2222-2222-222222222222","role":"authenticated"}',true);
select public.afirma((select count(*)=1 from public.conversas),'editor lê sua conversa');
select public.afirma((select count(*)=2 from public.mensagens),'editor lê suas mensagens');
do $$ begin begin update public.loja_recursos set ativo=false where recurso='chat_persistente'; raise exception 'aceitou'; exception when insufficient_privilege then null; end; end $$;
select public.afirma(true,'editor não altera flag do chat');
do $$ begin begin insert into public.mensagens(loja_id,user_id,conversa_id,papel,conteudo,idempotency_key) values('aaaaaaaa-0000-0000-0000-000000000001',auth.uid(),gen_random_uuid(),'usuario','x','teste-123'); raise exception 'aceitou'; exception when insufficient_privilege then null; end; end $$;
select public.afirma(true,'escrita direta bloqueada');
select public.afirma(not public.chat_definir_retencao('aaaaaaaa-0000-0000-0000-000000000001',30),'editor não muda retenção');
reset role;
insert into public.loja_recursos(loja_id,recurso,ativo) values('aaaaaaaa-0000-0000-0000-000000000001','chat_leitura_administrativa',true);
grant select on turno to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"33333333-3333-3333-3333-333333333333","role":"authenticated"}',true);
select public.afirma((select count(*)=0 from public.mensagens),'outra loja não lê mensagens');
do $$ begin begin perform * from public.chat_ler_como_administrador('bbbbbbbb-0000-0000-0000-000000000002',(select (j->>'conversa_id')::uuid from turno),'Motivo administrativo'); raise exception 'aceitou'; exception when insufficient_privilege then null; end; end $$;
select public.afirma(true,'admin de outra loja não atravessa tenant');
select set_config('request.jwt.claims','{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated"}',true);
select public.afirma((select count(*)=2 from public.chat_ler_como_administrador('aaaaaaaa-0000-0000-0000-000000000001',(select (j->>'conversa_id')::uuid from turno),'Suporte solicitado pelo usuário')),'leitura explícita autorizada funciona');
select public.afirma(not public.chat_excluir((select (j->>'conversa_id')::uuid from turno)),'administrador não exclui conversa alheia');
select public.afirma(public.chat_definir_retencao('aaaaaaaa-0000-0000-0000-000000000001',30),'lojista configura retenção por RPC');
reset role;
select public.afirma(exists(select 1 from public.auditoria where acao='chat.leitura_administrativa'),'leitura administrativa auditada');
select public.afirma(not exists(select 1 from public.auditoria where depois::text like '%Produto sintético%'),'conteúdo não vaza para auditoria');
-- Mensagem antiga deve desaparecer mesmo em conversa ativa; inserir fixture antiga, nunca alterar mensagem real.
insert into public.mensagens(loja_id,user_id,conversa_id,papel,conteudo,idempotency_key,criada_em) values('aaaaaaaa-0000-0000-0000-000000000001','22222222-2222-2222-2222-222222222222',(select (j->>'conversa_id')::uuid from turno),'usuario','Vencida','chave-vencida-1',now()-interval '31 days');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"22222222-2222-2222-2222-222222222222","role":"authenticated"}',true);
select public.afirma((select count(*)=2 from public.mensagens),'RLS oculta mensagem vencida antes do expurgo');
reset role;
select public.afirma(public.chat_expurgar()=1,'expurgo elimina mensagem antiga sem apagar conversa ativa');
select public.afirma((select count(*)=1 from public.conversas),'conversa ativa preservada');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"22222222-2222-2222-2222-222222222222","role":"authenticated"}',true);
select public.afirma(public.chat_excluir((select (j->>'conversa_id')::uuid from turno)),'titular exclui conversa');
reset role;
select public.afirma((select count(*)=0 from public.mensagens),'exclusão remove mensagens');
select public.afirma(exists(select 1 from public.auditoria where acao='chat.excluido'),'auditoria preservada após exclusão');

select public.afirma(not has_function_privilege('anon','public.chat_iniciar(uuid,uuid,uuid,text,text,text)','EXECUTE'),'anônimo não cria turno por RPC');
select public.afirma(not has_function_privilege('authenticated','public.chat_responder(uuid,uuid,uuid,uuid,text,jsonb)','EXECUTE'),'usuário não forja resposta por RPC');
select public.afirma((select chat_retencao_dias=180 from lojas where slug='chat-b'),'retenção inicial 180 dias');
update public.recursos_plataforma set disponivel=false where codigo='chat_persistente';
select public.afirma(not private.chat_recurso('aaaaaaaa-0000-0000-0000-000000000001','chat_persistente'),'desligamento global prevalece sobre a loja');
update public.recursos_plataforma set disponivel=true where codigo='chat_persistente';
delete from public.loja_recursos where recurso='chat_leitura_administrativa';
update public.recursos_plataforma set ativo_padrao=true where codigo='chat_leitura_administrativa';
select public.afirma(not private.chat_recurso('aaaaaaaa-0000-0000-0000-000000000001','chat_leitura_administrativa'),'leitura administrativa exige permissão individual por loja');
set local role authenticated;
select set_config('request.jwt.claims','{}',true);
select public.afirma(not public.chat_excluir(gen_random_uuid()),'ausência de uid não exclui conversa');
select public.afirma(not public.chat_definir_retencao('aaaaaaaa-0000-0000-0000-000000000001',null),'retenção nula negada');
reset role;
create temp table t2 as select public.chat_iniciar('aaaaaaaa-0000-0000-0000-000000000001','22222222-2222-2222-2222-222222222222',null,'Pergunta teste','idempotencia-nova-1','compativel_openai') j;
do $$ begin begin perform public.chat_responder('aaaaaaaa-0000-0000-0000-000000000001','22222222-2222-2222-2222-222222222222',(select(j->>'pergunta_id')::uuid from t2),gen_random_uuid(),'forjada','{}'); raise exception 'aceitou'; exception when insufficient_privilege then null; end; end $$;
select public.afirma((select count(*)=1 from public.mensagens),'token incorreto não grava resposta');
do $$ begin begin update public.mensagens set conteudo='alterada'; raise exception 'aceitou'; exception when insufficient_privilege then null; end; end $$;
select public.afirma(true,'mensagens imutáveis inclusive para serviço');
do $$ begin begin insert into public.mensagens(loja_id,user_id,conversa_id,papel,conteudo,idempotency_key) values('bbbbbbbb-0000-0000-0000-000000000002','33333333-3333-3333-3333-333333333333',(select(j->>'conversa_id')::uuid from t2),'usuario','vazamento','idem-cruzada-1'); raise exception 'aceitou'; exception when foreign_key_violation then null; end; end $$;
select public.afirma(true,'chave composta impede associar mensagem a conversa de outra loja');
-- Integração do contador real de uso: a gravação final deve cobrar uma vez, junto da mensagem/auditoria.
select public.ia_salvar_chave('aaaaaaaa-0000-0000-0000-000000000001','compativel_openai','v2.k1.sintetico','test','gpt-sintetico',1000,'https://api.openai.com/v1');
select public.chat_responder('aaaaaaaa-0000-0000-0000-000000000001','22222222-2222-2222-2222-222222222222',(select(j->>'pergunta_id')::uuid from t2),(select(j->>'turno_token')::uuid from t2),'Resposta sintética','{"tokens":10,"provedor":"compativel_openai","simulado":true,"desfecho":"ok"}');
select public.afirma((select tokens_mes=10 from public.loja_chaves_ia where provedor='compativel_openai'),'uso contabilizado junto da resposta');
select public.chat_iniciar('aaaaaaaa-0000-0000-0000-000000000001','22222222-2222-2222-2222-222222222222',null,'Pergunta teste','idempotencia-nova-1','compativel_openai');
select public.afirma((select tokens_mes=10 from public.loja_chaves_ia where provedor='compativel_openai'),'recuperação não contabiliza tokens duas vezes');
insert into public.mensagens(loja_id,user_id,conversa_id,papel,conteudo,idempotency_key,criada_em) values('aaaaaaaa-0000-0000-0000-000000000001','22222222-2222-2222-2222-222222222222',(select(j->>'conversa_id')::uuid from t2),'usuario','Não ressuscitar','idempotencia-vencida-2',now()-interval '31 days');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated"}',true);
select public.afirma(public.chat_definir_retencao('aaaaaaaa-0000-0000-0000-000000000001',180),'retenção pode ser estendida de forma auditada');
reset role;
select public.afirma(not exists(select 1 from public.mensagens where conteudo='Não ressuscitar'),'aumento de retenção não ressuscita mensagem vencida');
rollback;
